import{_ as t,o,c as n,l as r,t as a,N as i}from"./chunks/framework.Bbd9fWQx.js";const b=JSON.parse('{"title":"join | x-cmd man (man1) | join lines of two files on a common field","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | join - join lines of two files on a common field","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"join | x-cmd man (man1) | join lines of two files on a common field"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | join - join lines of two files on a common field"}]]},"headers":[],"params":{"isMan":true,"man":"join","category":"man1","desc":"join lines of two files on a common field"},"relativePath":"man1/join.md","filePath":"man1/join.md"}'),s={name:"man1/join.md"},d={class:"visually-hidden"},l=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>join - join lines of two files on a common field</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>join</strong> [<em>OPTION</em>]... <em>FILE1 FILE2</em></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>For each pair of input lines with identical join fields, write a line to standard output. The default join field is the first, delimited by blanks.</p><p>When FILE1 or FILE2 (not both) is -, read standard input.</p><dl><dt><strong>-a</strong> FILENUM</dt><dd>also print unpairable lines from file FILENUM, where FILENUM is 1 or 2, corresponding to FILE1 or FILE2</dd><dt><strong>-e</strong> STRING</dt><dd>replace missing (empty) input fields with STRING; I.e., missing fields specified with &#39;-12jo&#39; options</dd><dt><strong>-i</strong>, <strong>--ignore-case</strong></dt><dd>ignore differences in case when comparing fields</dd><dt><strong>-j</strong> FIELD</dt><dd>equivalent to &#39;-1 FIELD <strong>-2</strong> FIELD&#39;</dd><dt><strong>-o</strong> FORMAT</dt><dd>obey FORMAT while constructing output line</dd><dt><strong>-t</strong> CHAR</dt><dd>use CHAR as input and output field separator</dd><dt><strong>-v</strong> FILENUM</dt><dd>like <strong>-a</strong> FILENUM, but suppress joined output lines</dd><dt><strong>-1</strong> FIELD</dt><dd>join on this FIELD of file 1</dd><dt><strong>-2</strong> FIELD</dt><dd>join on this FIELD of file 2</dd><dt><strong>--check-order</strong></dt><dd>check that the input is correctly sorted, even if all input lines are pairable</dd><dt><strong>--nocheck-order</strong></dt><dd>do not check that the input is correctly sorted</dd><dt><strong>--header</strong></dt><dd>treat the first line in each file as field headers, print them without trying to pair them</dd><dt><strong>-z</strong>, <strong>--zero-terminated</strong></dt><dd>line delimiter is NUL, not newline</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>Unless <strong>-t</strong> CHAR is given, leading blanks separate fields and are ignored, else fields are separated by CHAR. Any FIELD is a field number counted from 1. FORMAT is one or more comma or blank separated specifications, each being &#39;FILENUM.FIELD&#39; or &#39;0&#39;. Default FORMAT outputs the join field, the remaining fields from FILE1, the remaining fields from FILE2, all separated by CHAR. If FORMAT is the keyword &#39;auto&#39;, then the first line of each file determines the number of fields output for each line.</p><p>Important: FILE1 and FILE2 must be sorted on the join fields. E.g., use &quot;sort <strong>-k</strong> 1b,1&quot; if &#39;join&#39; has no options, or use &quot;join <strong>-t</strong> &#39;&#39;&quot; if &#39;sort&#39; has no options. Note, comparisons honor the rules specified by &#39;LC_COLLATE&#39;. If the input is not sorted and some lines cannot be joined, a warning message will be given.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Mike Haertel.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>comm</strong>(1), <strong>uniq</strong>(1)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/join%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/join\\</a>&gt; <br> or available locally via: info &#39;(coreutils) join invocation&#39;</p>',19);function h(e,g,p,c,f,m){return o(),n("div",null,[r("h1",d,a(e.$params.man),1),l])}const I=t(s,[["render",h]]);export{b as __pageData,I as default};
